WITH src AS (SELECT * FROM subscriptions WHERE status IN ('CANCELLED', 'PAUSED') AND monthly_fee BETWEEN 90 AND 170), summary AS (SELECT status, CASE WHEN YEAR(start_date) < 2024 THEN 'before_2024' WHEN YEAR(start_date) = 2024 THEN '2024' ELSE 'after_2024' END AS start_cohort, ROUND((100 * SUM(CASE WHEN plan = 'premium' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_premium, ROUND((100 * SUM(CASE WHEN status = 'EXPIRED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_expired FROM src GROUP BY status, CASE WHEN YEAR(start_date) < 2024 THEN 'before_2024' WHEN YEAR(start_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT status, start_cohort, pct_premium, pct_expired FROM summary WHERE pct_premium > 65
